#!/usr/bin/env node

// Quick test script for basic functionality
// Usage: npm run quick-test

console.log('🚀 Quick MCP Server Test');
console.log('========================');

// Check environment
if (!process.env.GET_NOTE_API_KEY) {
  console.error('❌ Please set GET_NOTE_API_KEY first:');
  console.error('export GET_NOTE_API_KEY="your-api-key-here"');
  process.exit(1);
}

console.log('✅ Environment configured');
console.log(`   API Key: ${process.env.GET_NOTE_API_KEY.substring(0, 8)}...`);
console.log(`   Topic ID: ${process.env.GET_NOTE_TOPIC_ID || 'Not set (optional)'}`);

// Test basic functionality
import { spawn } from 'child_process';

console.log('');
console.log('🧪 Testing basic functionality...');

// Test 1: Help command
console.log('1. Testing help command...');
const helpTest = spawn('node', ['src/index.js', '--help'], {
  env: { ...process.env },
  stdio: 'pipe'
});

helpTest.stdout.on('data', (data) => {
  if (data.toString().includes('get-notes-mcp')) {
    console.log('   ✅ Help command works');
  }
});

helpTest.on('close', (code) => {
  if (code === 0) {
    console.log('   ✅ Help command completed');
  } else {
    console.log('   ❌ Help command failed');
  }
  
  // Test 2: Tool list
  console.log('');
  console.log('2. Testing tool list...');
  
  const toolTest = spawn('node', ['src/index.js'], {
    env: { ...process.env },
    stdio: 'pipe'
  });
  
  let output = '';
  toolTest.stdout.on('data', (data) => {
    output += data.toString();
  });
  
  toolTest.stdin.write('{"jsonrpc":"2.0","method":"tools/list","id":1}\n');
  
  setTimeout(() => {
    toolTest.stdin.end();
  }, 1000);
  
  toolTest.on('close', (code) => {
    if (output.includes('tools')) {
      console.log('   ✅ Tool list works');
    } else {
      console.log('   ❌ Tool list failed');
      console.log('   Output:', output.substring(0, 200));
    }
    
    console.log('');
    console.log('🎯 Inspector Test Setup:');
    console.log('========================');
    console.log('');
    console.log('To test with MCP Inspector, run:');
    console.log('   npx @modelcontextprotocol/inspector');
    console.log('');
    console.log('Then configure:');
    console.log('   Command: npx');
    console.log('   Arguments: get-biji-mcp');
    console.log('   Environment: GET_NOTE_API_KEY=' + process.env.GET_NOTE_API_KEY.substring(0, 8) + '...');
    console.log('');
    console.log('✅ Quick test completed!');
  });
});